// OpsServiceHandler is an implementation of the mistgate.ops.v1.OpsService service.
type OpsServiceHandler interface {
	// The log level now in force, the one the panel started with, and the size of the ring.
	GetLogSettings(context.Context, *connect.Request[v1.GetLogSettingsRequest]) (*connect.Response[v1.GetLogSettingsResponse], error)
	// Changes the level until the next restart; the panel goes back to its configured default (--log-level or MISTGATE_LOG_LEVEL).
	SetLogLevel(context.Context, *connect.Request[v1.SetLogLevelRequest]) (*connect.Response[v1.SetLogLevelResponse], error)
	// The panel's recent log records, newest first, with their text scrubbed (addresses, secret names, key-shaped values) and only
	// the attribute keys of an allow-list. A read: every record is cleaned on the way out.
	GetPanelLogs(context.Context, *connect.Request[v1.GetPanelLogsRequest]) (*connect.Response[v1.GetPanelLogsResponse], error)
	// How long each pruned table keeps its rows: the owner's values and the defaults.
	GetRetention(context.Context, *connect.Request[v1.GetRetentionRequest]) (*connect.Response[v1.GetRetentionResponse], error)
	// Changes some of them. A value outside its limits is INVALID_ARGUMENT; a field left out stays as it is.
	SetRetention(context.Context, *connect.Request[v1.SetRetentionRequest]) (*connect.Response[v1.SetRetentionResponse], error)
	// Streams newline-delimited JSON of the timeline events, the audit log, the node journal and the panel's logs of a window.
	// Every row is scrubbed like panel_logs. The stream is a download: the admin UI saves it as a file.
	ExportData(context.Context, *connect.Request[v1.ExportDataRequest], *connect.ServerStream[v1.ExportDataResponse]) error
	// Whether /metrics is on and whether it has a token. The token itself is never returned here.
	GetMetricsSettings(context.Context, *connect.Request[v1.GetMetricsSettingsRequest]) (*connect.Response[v1.GetMetricsSettingsResponse], error)
	// Turns /metrics on or off and, with rotate_token, makes a new token; the token is in this response once and only its hash is
	// stored. Turning it on without a token makes one.
	SetMetricsSettings(context.Context, *connect.Request[v1.SetMetricsSettingsRequest]) (*connect.Response[v1.SetMetricsSettingsResponse], error)
	// DEBUG CAPTURE of one node (agent capability "debug/1"). Starts it: the node raises its log level for the chosen sources for up
	// to 15 minutes, keeps the records in a bounded buffer and ships them, scrubbed, when the time is up. An agent without the
	// capability is FAILED_PRECONDITION "agent too old"; a node that is offline is FAILED_PRECONDITION "node is offline". Admin
	// profile tokens start one only through an approved plan (node_debug_capture_plan / _apply); it is audit-logged.
	StartDebugCapture(context.Context, *connect.Request[v1.StartDebugCaptureRequest]) (*connect.Response[v1.StartDebugCaptureResponse], error)
	// Ends a running capture now: the node ships what it holds. A capture that is already over is returned as it is.
	StopDebugCapture(context.Context, *connect.Request[v1.StopDebugCaptureRequest]) (*connect.Response[v1.StopDebugCaptureResponse], error)
	// The captures the panel still holds for a node (24 hours), newest first.
	ListDebugCaptures(context.Context, *connect.Request[v1.ListDebugCapturesRequest]) (*connect.Response[v1.ListDebugCapturesResponse], error)
	// The records of one capture, oldest first, with filters. Every record passes the panel's scrubbers again on the way out.
	GetDebugCapture(context.Context, *connect.Request[v1.GetDebugCaptureRequest]) (*connect.Response[v1.GetDebugCaptureResponse], error)
	// What the panel itself costs: its process (CPU, memory, Go runtime, threads, descriptors), the machine it runs on, its
	// database and the admin API's load over the last minutes. Numbers only: no address, path or name of a person.
	GetPanelResources(context.Context, *connect.Request[v1.GetPanelResourcesRequest]) (*connect.Response[v1.GetPanelResourcesResponse], error)
	// How loaded each node was over a window of its hourly host load (GetNodeHostHistory's rows), what it runs out of first,
	// how many more people it can take and what to do about it, with a fleet summary. It never contacts a node.
	GetFleetLoad(context.Context, *connect.Request[v1.GetFleetLoadRequest]) (*connect.Response[v1.GetFleetLoadResponse], error)
	// The per-inbound ASN setting and facts about the panel's currently loaded trusted table and node support.
	GetNetworkSettings(context.Context, *connect.Request[v1.GetNetworkSettingsRequest]) (*connect.Response[v1.GetNetworkSettingsResponse], error)
	// Changes the mode. Turning networks off removes the stored hourly and per-person rows.
	SetNetworkSettings(context.Context, *connect.Request[v1.SetNetworkSettingsRequest]) (*connect.Response[v1.SetNetworkSettingsResponse], error)
	// LOGS FOR SUPPORT: the owner asks one device of the Mistgate app (a device with a key) for its logs. The person sees the request in
	// the app at its next sync and sends the logs or refuses. At most one request is open per device; it runs out after 72 hours.
	// NOT_FOUND: no such device with a key. FAILED_PRECONDITION: the device has an open request. Owner-only, closed to tokens, audit-logged.
	// The panel keeps the logs (and the request) 7 days; GetClientDebug, ExportClientDebug and DeleteClientDebug read, download and delete them.
	RequestClientDebug(context.Context, *connect.Request[v1.RequestClientDebugRequest]) (*connect.Response[v1.RequestClientDebugResponse], error)
	// Withdraws an open request. NOT_FOUND: no such request. FAILED_PRECONDITION: it is not open (answered, refused, withdrawn or run out).
	CancelClientDebug(context.Context, *connect.Request[v1.CancelClientDebugRequest]) (*connect.Response[v1.CancelClientDebugResponse], error)
	// The requests and the bundles people sent on their own, newest first, at most 100: of one person, or of everyone.
	ListClientDebug(context.Context, *connect.Request[v1.ListClientDebugRequest]) (*connect.Response[v1.ListClientDebugResponse], error)
	// The records of one received bundle, oldest first, with filters (GetDebugCapture's shape). The text is what the panel stored when
	// the bundle came, passed once more through the panel's current secret names; the attributes are the contract's keys. The first read
	// of a bundle is audit-logged. NOT_FOUND: no such id. FAILED_PRECONDITION: the request holds no logs. Owner-only, closed to tokens.
	GetClientDebug(context.Context, *connect.Request[v1.GetClientDebugRequest]) (*connect.Response[v1.GetClientDebugResponse], error)
	// A bundle as NDJSON (one record per line: seq, ts, lvl, src, msg, kv), the same records GetClientDebug returns. Needs a fresh
	// sign-in (step-up); every download is audit-logged. Owner-only, closed to tokens.
	ExportClientDebug(context.Context, *connect.Request[v1.ExportClientDebugRequest], *connect.ServerStream[v1.ExportClientDebugResponse]) error
	// Deletes a request that is closed, or a bundle, with its records. FAILED_PRECONDITION: the request is still open (cancel it).
	// Audit-logged. Owner-only, closed to tokens.
	DeleteClientDebug(context.Context, *connect.Request[v1.DeleteClientDebugRequest]) (*connect.Response[v1.DeleteClientDebugResponse], error)
}

